DECLARE
    V_REQUEST_ID   RAW(16);
    V_TERMINAL_ID  RAW(16);
BEGIN

    /* Request ID */
    V_REQUEST_ID :=
        HEXTORAW(
            REPLACE(
                '{{ appsmith.URL.queryParams.requestId }}',
                '-',
                ''
            )
        );

    /* Terminal ID captured when Delete was clicked */
    V_TERMINAL_ID :=
        HEXTORAW(
            REPLACE(
                '{{ appsmith.store.MMS_TERMINAL_DELETE_ID }}',
                '-',
                ''
            )
        );

    /* Soft delete terminal */
    TALY_BO_REP.MMS_TERMINAL_PKG.DELETE_TERMINAL(
        P_REQUEST_ID  => V_REQUEST_ID,
        P_TERMINAL_ID => V_TERMINAL_ID
    );

END;
